/**
 * llama.cpp server controller.
 *
 * The studio tries to launch a real local `llama-server` (the official
 * llama.cpp HTTP server) with the right --n-gpu-layers / --tensor-split
 * settings that mirror the layer placement plan.
 *
 * When `llama-server` is not on PATH (which is the case in many CI / preview
 * environments), the controller flips into "demo" mode and the WebSocket
 * service streams simulated tokens generated by z-ai-web-dev-sdk through the
 * layer pipeline. The UI shows the same layer movement either way.
 */

import "server-only"
import { spawn, ChildProcess } from "node:child_process"
import { existsSync } from "node:fs"
import { join } from "node:path"
import { db } from "@/lib/db"
import { getLayersForModel, planPlacement, applyPlan, type Strategy } from "@/lib/layer-engine"
import { modelLocalPath } from "@/lib/hf"

const SERVER_BIN =
  process.env.LLAMA_SERVER_BIN ??
  join(process.cwd(), "bin", "llama", process.platform === "win32" ? "llama-server.exe" : "llama-server")

export interface LlamaStatus {
  available: boolean
  running: boolean
  mode: "real" | "demo" | "unknown"
  pid?: number
  port?: number
  endpoint?: string
  error?: string
  nGpuLayers?: number
  contextSize?: number
}

let currentProcess: ChildProcess | null = null
let currentModelId: string | null = null
let currentStrategy: Strategy = "balanced"
let currentMode: "real" | "demo" | "unknown" = "unknown"

/** Check whether a llama-server binary is reachable */
export async function detectLlamaServer(): Promise<boolean> {
  if (existsSync(SERVER_BIN)) return true
  const cmd = process.platform === "win32" ? "where" : "which"
  return new Promise<boolean>((resolve) => {
    const child = spawn(cmd, ["llama-server"], { stdio: "ignore", windowsHide: true })
    child.on("exit", (code) => resolve(code === 0))
    child.on("error", () => resolve(false))
  })
}

export function currentStatus(): LlamaStatus {
  if (currentMode === "unknown") {
    return {
      available: false,
      running: false,
      mode: "unknown",
    }
  }
  return {
    available: currentMode === "real",
    running: currentProcess !== null || currentMode === "demo",
    mode: currentMode,
    pid: currentProcess?.pid,
    port: 8080,
    endpoint: currentMode === "real" ? "http://127.0.0.1:8080" : undefined,
    nGpuLayers: 0,
  }
}

export function currentEngineModelId(): string | null {
  return currentModelId
}

export function currentEngineStrategy(): Strategy {
  return currentStrategy
}

/**
 * "Load" a model: compute the placement plan, apply it to the DB, and try
 * to launch a real llama-server pointing at the first .gguf file. If the
 * binary is missing, switch to demo mode (no subprocess).
 */
export async function loadModel(modelId: string, strategy: Strategy = "balanced"): Promise<LlamaStatus> {
  // Stop any existing engine first
  await stopEngine()

  const model = await db.model.findUnique({ where: { id: modelId } })
  if (!model) throw new Error("Model not found")

  const layers = await getLayersForModel(modelId)
  const plan = planPlacement(layers, strategy, { contextBytes: model.contextSize * 4096 })
  await applyPlan(modelId, plan)

  currentModelId = modelId
  currentStrategy = strategy

  const realAvailable = await detectLlamaServer()
  if (!realAvailable || !model.localPath) {
    currentMode = "demo"
    currentProcess = null
    return {
      available: false,
      running: true,
      mode: "demo",
      contextSize: model.contextSize,
      nGpuLayers: Array.from(plan.placement.values()).filter((l) => l === "gpu").length,
    }
  }

  // We have a real llama-server: spawn it pointing at the first shard.
  // ngl = number of GPU layers — this matches the studio's GPU placement.
  const ngl = Array.from(plan.placement.values()).filter((l) => l === "gpu").length
  const firstShard = layers[0]?.fileName
  if (!firstShard) {
    currentMode = "demo"
    return { available: false, running: true, mode: "demo" }
  }

  const args = [
    "--model", join(model.localPath, firstShard),
    "--ctx-size", String(model.contextSize),
    "--n-gpu-layers", String(ngl),
    "--host", "127.0.0.1",
    "--port", "8080",
    "--parallel", "1",
    "--no-webui",
    "--jinja",
    "--no-kv-offload",
    "--threads", String(Math.max(1, Math.floor((await import("node:os")).cpus().length / 2))),
  ]

  try {
    currentProcess = spawn(SERVER_BIN, args, { stdio: "ignore", windowsHide: true })
    currentMode = "real"
    currentProcess.on("error", () => {
      currentMode = "demo"
      currentProcess = null
    })
    currentProcess.on("exit", () => {
      currentProcess = null
    })
    return {
      available: true,
      running: true,
      mode: "real",
      pid: currentProcess.pid,
      port: 8080,
      endpoint: "http://127.0.0.1:8080",
      nGpuLayers: ngl,
      contextSize: model.contextSize,
    }
  } catch (err) {
    currentMode = "demo"
    currentProcess = null
    return {
      available: false,
      running: true,
      mode: "demo",
      error: String(err),
    }
  }
}

/** Stop the engine */
export async function stopEngine(): Promise<void> {
  if (currentProcess) {
    try {
      currentProcess.kill("SIGTERM")
    } catch {}
    currentProcess = null
  }
  currentMode = "unknown"
  currentModelId = null
}

/**
 * Issue a /completion request to a real llama-server. Returns a stream of
 * tokens. In demo mode this is unused — the WebSocket service uses the
 * z-ai-web-dev-sdk instead.
 */
export async function* streamCompletion(
  prompt: string,
  opts: { temperature?: number; maxTokens?: number; system?: string } = {},
): AsyncGenerator<string, void, unknown> {
  if (currentMode !== "real" || !currentStatus().endpoint) {
    throw new Error("Engine not in real mode")
  }
  const res = await fetch(`${currentStatus().endpoint}/completion`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      prompt: opts.system ? `${opts.system}\n\n${prompt}` : prompt,
      n_predict: opts.maxTokens ?? 256,
      temperature: opts.temperature ?? 0.7,
      stream: true,
    }),
  })
  if (!res.ok || !res.body) throw new Error(`llama-server error ${res.status}`)
  const reader = (res.body as unknown as ReadableStream<Uint8Array>).getReader()
  const decoder = new TextDecoder()
  let buf = ""
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    buf += decoder.decode(value, { stream: true })
    let idx
    while ((idx = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, idx).trim()
      buf = buf.slice(idx + 1)
      if (!line.startsWith("data:")) continue
      try {
        const json = JSON.parse(line.slice(5).trim())
        if (json.content) yield json.content as string
      } catch {}
    }
  }
}

/** Mark demo mode explicitly (used when the user picks "demo" intentionally) */
export function setDemoMode(): void {
  currentMode = "demo"
  currentProcess = null
}

export { modelLocalPath }
